let isSupport = 0;
try {
  const match = raw.match(/\{[\s\S]*\}/);
  const parsed = JSON.parse(match ? match[0] : raw);
  isSupport = (parsed.is_support === true || String(parsed.is_support).toLowerCase() === 'true') ? 1 : 0;
} catch (e) {
  isSupport = /"?is_support"?\s*:\s*true/i.test(raw) ? 1 : 0;
}
return { json: { answers: { is_support: { noul: isSupport } } } };

