parameters.jsCode:
const history = Array.isArray($json.history) ? $json.history : [];

function clean(text, role) {
  let t = String(text || '');
  if (role === 'human') {
    const subj = (t.match(/Email subject:\s*(?:Subject:\s*)?(.*)/i) || [])[1] || '';
    const m = t.match(/Email body:\s*([\s\S]*?)(?=\n\s*On [\s\S]{0,250}?wrote:|\n>|\n\s*From:|\n\s*Context:|$)/i);
    const body = (m ? m[1] : t).trim();
    t = (subj ? 'Subject: ' + subj.trim() + '\n' : '') + body;
  }
  t = t.split(/\n\s*Context:/i)[0];
  t = t.split(/\n\s*Email name:/i)[0];
  if (role === 'ai') t = t.replace(/<br\s*\/?>/gi, '\n').replace(/<\/p>/gi, '\n').replace(/<li>/gi, '- ').replace(/<[^>]+>/g, '');
  return t.replace(/\n{3,}/g, '\n\n').trim().slice(0, 1500);
}

const chat_history = history
  .filter(m => m.type === 'human' || m.type === 'ai')
  .map(m => ({ role: m.type, message: clean(m.content, m.type) }))
  .filter(m => m.message && !/^ESCALATE/i.test(m.message));

const chat_text = chat_history
  .map(m => (m.role === 'human' ? 'CUSTOMER: ' : 'OUR SUPPORT REPLY: ') + m.message)
  .join('\n\n');

return { json: { chat_history, chat_text } };

const mail = $('Gmail Trigger').item.json;

const rawSubject = String(mail.subject || '').trim().slice(0, 60);

// Swap any backticks already in the subject for apostrophes, then wrap it
const subject = '`' + rawSubject.replace(/`/g, "'") + '`';

// Random case ID, e.g. K7Q2ZP
const caseId = Math.random().toString(36).slice(2, 8).toUpperCase();

return {
  json: {
    caseId,
    subject
  }
};

const raw = String($json.output || '').trim();

// Read the keyword on the first line. No keyword means ASK, so a model slip never emails a customer.
const match = raw.match(/^\s*(ASK|DRAFT|SEND)\s*:\s*/i);
const action = match ? match[1].toUpperCase() : 'ASK';
const message = match ? raw.slice(match[0].length).trim() : raw;

// Slack can't render HTML, so make a readable plain-text version
const toSlack = (t) => String(t)
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<\/p>/gi, '\n\n')
  .replace(/<li>/gi, '- ')
  .replace(/<\/li>/gi, '\n')
  .replace(/<[^>]+>/g, '')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

let slackText = toSlack(message);

if (action === 'DRAFT') {
  // Split at the QUESTION: marker. Everything before it is the draft, everything after is the question.
  const m = message.match(/^([\s\S]*?)\n?\s*QUESTION:\s*([\s\S]*)$/i);

  if (m) {
    let draftPart = toSlack(m[1]);
    const question = toSlack(m[2]).split('\n')[0].trim();

    // Remove the extra "Please let me know if I should send..." line the model adds
    // after the sign-off, so only the email itself stays in the block
    const signOff = draftPart.search(/Onkya Services Support/i);
    if (signOff !== -1) {
      draftPart = draftPart.slice(0, signOff + 'Onkya Services Support'.length);
    }

    const draft = draftPart.trim().replace(/`/g, "'");
    slackText = '```' + draft + '```\n\n' + question;
  }
  // No QUESTION: marker found: leave slackText as plain text so nothing breaks
}

return { json: { action, message, slackText } };

const mail = $input.item.json;
const raw = String(mail.text || '').replace(/\r/g, '');

// Find where the quoted history starts and cut there
const patterns = [
  /(^|\n)\s*On [\s\S]{0,250}?wrote:/i,        // "On Thu, ... wrote:"
  /\n-{2,}\s*Original Message\s*-{2,}/i,      // Outlook style
  /\nFrom:\s.+\nSent:\s/i,                    // Outlook headers
  /\n>/                                       // first quoted line
];

let cut = raw.length;
for (const p of patterns) {
  const pos = raw.search(p);
  if (pos !== -1 && pos < cut) cut = pos;
}

const latestText = raw.slice(0, cut).trim() || raw.trim();

return {
  json: {
    latestText: latestText.slice(0, 3000),
    subject: mail.subject,
    from: mail.from,
    id: mail.id,
    threadId: mail.threadId
  }
};

const MIN_SCORE = 0.4;
const all = $input.item.json.snippets || [];

// Keep only relevant snippets, best first, max 3
const snippets = [...all]
  .filter(s => (s.score || 0) >= MIN_SCORE)
  .sort((a, b) => (b.score || 0) - (a.score || 0))
  .slice(0, 3);

// Best score across everything returned
const topScore = all.length ? Math.max(...all.map(s => s.score || 0)) : 0;

const context = snippets
  .map((s, i) => '[' + (i + 1) + '] ' + String(s.content || '').replace(/\r/g, '').trim().slice(0, 3000))
  .join('\n\n---\n\n');

const mail = $('Gmail Trigger').item.json;

return {
  json: {
    hasKnowledge: snippets.length > 0,
    topScore,
    context,
    from: mail.From,
    subject: mail.Subject,
    question: String(mail.text || mail.snippet || ''),
    threadId: mail.threadId,
    messageId: mail.id,
    threadLink: 'https://mail.google.com/mail/u/0/#inbox/' + mail.threadId
  }
};

const out = String($json.output || '').trim();
const latest = String($('Email Key Fields').item.json.latestText || '');

// 1. The agent itself asked to escalate (anywhere in the output, not just the start)
const agentEscalated = /ESCALATE/i.test(out);

// 2. Risky topics in the customer's newest message, whatever the agent said
const riskyEmail = /charged twice|double[- ]?charge|charged me|overcharg|wrong charge|refund|chargeback|dispute|unauthori[sz]ed|fraud|scam|lawyer|legal action|\bsue\b|police|complain/i.test(latest);

// 3. The agent promised an outcome it is not allowed to promise
const riskyReply = /you will be refunded|we will refund|refund (has been|will be)|if a refund is warranted|we have (checked|refunded|cancelled|processed)/i.test(out);

// 4. Empty or too short to be a real reply
const tooShort = out.length < 40;

let reason = '';
if (agentEscalated) reason = out.replace(/^[\s\S]*?ESCALATE:?\s*/i, '').split('\n')[0].trim() || 'Agent asked for a human';
else if (riskyEmail) reason = 'Billing, refund, fraud or legal wording in the email';
else if (riskyReply) reason = 'Draft promised an outcome only a human can decide';
else if (tooShort) reason = 'Agent reply was empty or too short';

return {
  json: {
    escalate: Boolean(reason),
    reason,
    reply: out
  }
};

const mail = $('Gmail Trigger').item.json;

const rawSubject = String(mail.subject || '').trim().slice(0, 60);

// Swap any backticks already in the subject for apostrophes, then wrap it
const subject = '`' + rawSubject.replace(/`/g, "'") + '`';

// Random case ID, e.g. K7Q2ZP
const caseId = Math.random().toString(36).slice(2, 8).toUpperCase();

return {
  json: {
    caseId,
    subject
  }
};

const out = $('Agent Output').item.json;
const row = $('Search records: Get thread Id').last().json.fields || {};

const channel = row.Channel;
const thread_ts = row.thread_ts;
const caseId = $('Get Email Subject').item.json.caseId;
const resumeUrl = $execution.resumeUrl;
const version = $runIndex; // goes up by 1 with every draft in the loop

const toSlack = (t) => String(t)
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<\/p>/gi, '\n\n')
  .replace(/<li>/gi, '- ')
  .replace(/<\/li>/gi, '\n')
  .replace(/<[^>]+>/g, '')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

// ASK (or anything that is not a draft): plain message, no button
if (out.action !== 'DRAFT') {
  const text = out.slackText;
  return [{
    json: {
      channel, thread_ts, text, caseId, version,
      blocks: [{ type: 'section', text: { type: 'mrkdwn', text } }]
    }
  }];
}

// DRAFT: keep only the email itself (drop any QUESTION line or stray text after the sign-off)
const message = String(out.message || '');
const q = message.match(/^([\s\S]*?)\n?\s*QUESTION:[\s\S]*$/i);
let draftHtml = (q ? q[1] : message).trim();
const signOff = draftHtml.search(/Onkya Services Support/i);
if (signOff !== -1) {
  draftHtml = draftHtml.slice(0, signOff + 'Onkya Services Support'.length).trim();
}

// Plain-text version for Slack, inside a code block (3000 character block limit)
const draftText = toSlack(draftHtml).replace(/`/g, "'").slice(0, 2800);
const draftBlock = { type: 'section', text: { type: 'mrkdwn', text: '```' + draftText + '```' } };

const blocks = [
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: 'Draft reply for the customer. Approve to send it as it is, or reply in this thread to ask for changes.'
    }
  },
  draftBlock,
  {
    type: 'actions',
    block_id: 'approval_buttons',
    elements: [{
      type: 'button',
      text: { type: 'plain_text', text: ':white_check_mark: Approve and send', emoji: true },
      style: 'primary',
      action_id: 'approve_draft',
      value: JSON.stringify({ caseId, version, resumeUrl })
    }]
  }
];

// Used later to replace the button once she clicks (chat.update)
const approvedBlocks = [
  draftBlock,
  { type: 'context', elements: [{ type: 'mrkdwn', text: ':white_check_mark: Approved and sent to the customer' }] }
];

return [{
  json: {
    channel, thread_ts, caseId, version,
    text: 'Draft reply ready for approval',
    blocks, approvedBlocks, draftHtml
  }
}];

