parameters.jsCode:
const body = $json.body || {};
const reply = String(body.reply || '').trim();

// Accept true or "true" in case the value gets stringified
const approvedFlag = body.approved === true || body.approved === 'true';

// Draft saved by Slack Request Prep. .last() gives the latest draft in the loop.
let draftHtml = '';
try {
  draftHtml = String($('Slack Request Prep').last().json.draftHtml || '').trim();
} catch (e) {}

let resumeKind = 'timeout';
if (approvedFlag) resumeKind = 'approved';
else if (reply) resumeKind = 'reply';

return {
  json: {
    resumeKind,
    reply,
    draftHtml,
    draftMissing: approvedFlag && !draftHtml,
    user: body.user,
    channel: body.channel,
    thread_ts: body.thread_ts,
    message_ts: body.message_ts,
    caseId: body.caseId,
    version: body.version
  }
};

